def kmeans(points, k, max_iter=100):
    centroids = [[float(v) for v in p] for p in points[:k]]
    labels = None
    for _ in range(max_iter):
        new_labels = []
        for p in points:
            best, best_distance = 0, None
            for j, c in enumerate(centroids):
                distance = sum((a - b) ** 2 for a, b in zip(p, c))
                if best_distance is None or distance < best_distance:       # strict: a tie keeps the lower index
                    best, best_distance = j, distance
            new_labels.append(best)
        if new_labels == labels:
            break
        labels = new_labels
        for j in range(k):
            members = [p for p, label in zip(points, labels) if label == j]
            if members:
                centroids[j] = [sum(column) / len(members) for column in zip(*members)]
    return labels, centroids
